import org.springframework.context.annotation.Lazy;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {
  private final OrderRepository orderRepository;
  private final PaymentClient paymentClient;

  // Self-injection: the container injects the PROXY (with the
  // transaction interceptor chain) instead of the raw bean, so
  // calling through it applies @Transactional correctly.
  @Lazy
  private final OrderService self;

  public OrderService(OrderRepository orderRepository, PaymentClient paymentClient,
                      @Lazy OrderService self) {
    this.orderRepository = orderRepository;
    this.paymentClient = paymentClient;
    this.self = self;
  }

  public void place(Order order) {
    self.saveAndCharge(order); // goes through the proxy
  }

  @Transactional
  public void saveAndCharge(Order order) {
    orderRepository.save(order);
    paymentClient.charge(order.total());
  }
}

// Cleaner alternatives: extract the transactional work into a
// separate @Service, or use TransactionTemplate directly.
